  "test": "from types import SimpleNamespace

import pytest

from langfuse._client.span_filter import is_app_root_eligible


def test_is_app_root_eligible_parent_without_scope():
    """A span that has a parent but no instrumentation scope should not be eligible as an app root."""
    span = SimpleNamespace(
        parent=SimpleNamespace(),
        instrumentation_scope=None,
        name="some-span",
    )
    assert is_app_root_eligible(span) is False


def test_is_app_root_eligible_no_parent_any_scope():
    """A span without a parent is always eligible, even if scope is missing."""
    span = SimpleNamespace(
        parent=None,
        instrumentation_scope=None,
        name="root-span",
    )
    assert is_app_root_eligible(span) is True
